// Ray trace plane from ray origin in ray direction.
float rtPlane(in vec3 ro, in vec3 rd, in vec4 pla)
{
    return -(pla.w + dot(pla.xyz, ro))/dot(pla.xyz, rd);
}

// Ray trace sphere from ray origin in ray direction.
float rtSphere(in vec3 ro, in vec3 rd, in vec3 sc, in float r)
{
    vec3 oc = ro - sc;
    float b = dot(rd, oc);
    float c = dot(oc, oc) - r*r;
    float t = b*b - c;

    if (0.0 > t)
        return -1.0;

    float g = sqrt(t);
    return min((-b + g), (-b - g));
}

// Get barycentric coordinates of p in triangle.
vec2 getBarycentric(in vec3 p, in mat3 tri)
{
    vec3 U = p - tri[0];
    vec3 V = tri[1] - tri[0];
    vec3 W = tri[2] - tri[0];

    float dVW = dot(V, W);
    mat2 A = mat2(vec2(dot(V, V), dVW), vec2(dVW, dot(W, W)));

    float dUV = dot(U, V);
    float dUW = dot(U, W);

    float d = determinant(A);

    if (abs(d)<1e-5)
        return vec2(-1,-1);

    return inverse(A) * vec2(dUV, dUW);
}

// Test if point in triangle.
bool pointInTriangle(in vec3 p, in mat3 tri, inout vec2 st)
{
	st = getBarycentric(p, tri);

    return (st[0] >= 0.0 && st[1] >= 0.0 && (st[0] + st[1] <= 1.0));
}

// Get plane for triangle.
vec4 getPlane(in mat3 tri)
{
    vec3 A = tri[0];
    vec3 B = tri[1];
    vec3 C = tri[2];

    vec3 AB = normalize(tri[1] - tri[0]);
    vec3 AC = normalize(tri[2] - tri[0]);
    vec3 K  = normalize(cross(AB, AC));

    return vec4(K, -dot(K, A));
}

vec3 Centroid(in mat3 tri)
{
    return (tri[0] + tri[1] + tri[2]) / 3.0;
}

mat3 rotateAboutCentroid(in mat3 rot, in mat3 tri)
{
    mat3 ctri = tri;
    vec3 c = Centroid(ctri);
    ctri[0] -= c;
    ctri[1] -= c;
    ctri[2] -= c;

    ctri = rot * ctri;
    ctri[0] += c;
    ctri[1] += c;
    ctri[2] += c;

    return ctri;
}

mat3 getCameraUVW(in vec3 w)
{
    vec3 u = normalize(cross(w,vec3(0,1,0)));
    vec3 v = normalize(cross(u, w));
    return mat3(u,v,-w);
}

float minDist = 100000.0;
void renderVertices(in vec3 ro, in vec3 rd, in mat3 tri, inout vec3 col)
{
    const float radius = .075;
    float t0 = rtSphere(ro, rd, tri[0], radius);
    float t1 = rtSphere(ro, rd, tri[1], radius);
    float t2 = rtSphere(ro, rd, tri[2], radius);

    if (!(0.0 > t0) && t0 < minDist)
        col = vec3(-5);//mix(col, vec3(0),0.975);
    if (!(0.0 > t1) && t1 < minDist)
        col = vec3(-5);//mix(col, vec3(0),0.975);
    if (!(0.0 > t2) && t2 < minDist)
        col = vec3(-5);//mix(col, vec3(0),0.975);
}

void mainImage( out vec4 O, in vec2 F )
{
    vec2 R = iResolution.xy,
        uv = (2.0 * F - R)/R.y,
        uv_0_1 = F/R;

    mat3 triangle = 1.5*mat3(vec3(-0.25, 0.93, 0.0), vec3(0.8, 0.53, 0.1), vec3(0.0, 0.4, -0.5));

    const vec3 sun_colour = vec3(1,1,.8);

    triangle = rotateAboutCentroid(mY(iTime*.1)*mZ(iTime*.2)*mX(iTime*.25), triangle);
    vec4 plane = getPlane(triangle);

    const float focal_length = 1.25;
    vec3 look_at = Centroid(triangle);
    vec3 ro = vec3(1.75, .2, 1.0);
    vec3 look_at_direction = normalize(look_at - ro);
    mat3 camUVW = getCameraUVW(look_at_direction);

    vec3 rd = camUVW * normalize(vec3(uv,-focal_length));

    vec3 col = min(vec3(.9),max(vec3(.3),(1.4 - exp(-1. * uv.y))*vec3(1)));//vec3(0.2,.87,1.1)));


    /////////////////////////////////////////////////////////////////
    //         Get the position on near plane of sun.
    /////////////////////////////////////////////////////////////////

    vec3 light_source = vec3(0.0,20.0,-10.);

    // The one that is not in terms of camera UVW coordinate system.
    vec4 near_plane = vec4(camUVW[2], focal_length);

    vec3 light_source_to_camera = normalize(ro - light_source);

    // Ray trace near plane from sun position towards camera.
    float t_projected_sun = rtPlane(light_source, light_source_to_camera, near_plane);

    vec3 projected_sun = inverse(camUVW) * (light_source + t_projected_sun * light_source_to_camera);

    vec2 sun_st = normalize(projected_sun.xy);

#if 0
    float t_sun = rtSphere(ro, rd, light_source, 0.05);
    if (!(0.0 > t_sun))
        col = vec3(1,0,0);
#endif

    float tPlane = rtPlane(ro, rd, vec4(0,1,0,0.25));
    bool ground_sees_sun = true;
    if (!(0.0 > tPlane))
    {
        vec3 p = ro + tPlane*rd;

        if (abs(p.x)<1.75 && abs(p.z)<1.75)
        {
            float smooth_factor = smoothstep(1.6, 0.9, abs(p.x))*smoothstep(1.6, 0.9, abs(p.z));
            col = mix(col,checkerboard(p,5.0)<0.5?vec3(.975):vec3(.925), smooth_factor);
            col = mix(col,vec3(1,0.7,0.3),0.3*smooth_factor);

            vec3 to_light = normalize(light_source - p);
            float t = rtPlane(p, to_light, plane);
            vec2 st;

            if (pointInTriangle(p + t*to_light, triangle, st))
            {
                ground_sees_sun = false;
                vec3 bar = vec3(st[0], st[1], 1.0 - st[0] - st[1]);
                // Taking min makes shadow have Y shape in centre.
                //float k = min(min(bar[0], bar[1]), bar[2]);
                // Thank you to Chronos who helped me to make it look more uniform by taking product instead.
                float k = bar[0] * bar[1] * bar[2];
                //float m = smoothstep(0.005, 0.05, k);
                col = mix(col,mix(col,vec3(0),pow(k,(1.0/2.5))),smooth_factor);
            }
        }
    }

    float tTri = rtPlane(ro, rd, plane);
    bool in_triangle = false;
    if (!(0.0 > tTri))
    {
        vec3 p = ro + tTri * rd;
        vec2 st;
        if (pointInTriangle(p, triangle, st))
        {
            in_triangle = true;
            minDist = tTri;
            /*
            float vx = abs(fract(st.x));
            float vy = abs(fract(st.y));
            float vz = abs(fract(1.0 - st.x - st.y));
            float kx = smoothstep( 0.0, 1.0, (vx - 0.036)/fwidth(vx));
            float ky = smoothstep( 0.0, 1.0, (vy - 0.036)/fwidth(vy));
            float kz = smoothstep( 0.0, 1.0, (vz - 0.036)/fwidth(vz));
            float mx = smoothstep(-1.0, 1.0, (abs(fract(5.0*st.x) - 0.0236) / fwidth(abs(fract(5.0*st.x)))));
            float my = smoothstep(-1.0, 1.0, (abs(fract(5.0*st.y) - 0.0236) / fwidth(abs(fract(5.0*st.y)))));
            */
            //st = st*2.0+noise(st*0.5 + fbm(st*5.0 - iTime*0.1 + fbm(st*20.0 + iTime*0.5)));
            st = (st*0.1 + fbm(st*2.0));
            st = (st*2.0 - noise(st*5.0));// + iTime*0.075));
            col = SS(0.0, 1.0, noise(st*3.0))*vec3(1.5);
        }
    }

    renderVertices(ro, rd, triangle, col);

    vec2 to_sun = sun_st - uv;

    if (ground_sees_sun)// && abs(sun_st.x)>1.0 && abs(sun_st.y)>1.0)
    {

        vec2 to_sun_normal = normalize(to_sun);
        to_sun_normal = ((to_sun_normal*10.0)+noise(to_sun_normal + iTime*0.2))/10.0;
        col += (
            !(0.0 > tTri) &&
            in_triangle   &&
            ground_sees_sun
                ? vec3(0)
                : texture(iChannel0, to_sun_normal).r * .3 * vec3(1,0.7,0.3) * (1.0 / max(.5,pow(length(to_sun),2.0)))
        );
    }
    // Output to screen
    O = vec4(gamma(col),1.0);
}

