#define gamma(c) pow(c, vec3(1.0/2.2))

#define SS(a,b,c) smoothstep(a,b,c)

// Get rotation matrix about X.
mat3 mX(in float t)
{
    float ct = cos(t);
    float st = sin(t);
    return mat3(
        1.0, 0.0, 0.0,
        0.0, ct, -st,
        0.0, st, ct
    );
}

// Get rotation matrix about Y.
mat3 mY(in float t)
{
    float ct = cos(t);
    float st = sin(t);
    return mat3(ct, 0.0, -st, 0.0, 1.0, 0.0, st, 0.0, ct);
}

// Get rotation matrix about Z.
mat3 mZ(in float t)
{
    float ct = cos(t);
    float st = sin(t);
    return mat3(
        ct, -st, 0.0,
        st,  ct, 0.0,
        0.0, 0.0, 1.0
    );
}

float checkerboard(vec3 p, float scale)
{
    vec2 coord = p.xz * scale;

    ivec2 i = ivec2(floor(coord));

    if ((i.x + i.y) % 2 == 0)
    {
        return 1.0;
    }
    else
    {
        return 0.0;
    }
}

vec2 random(vec2 st)
{
    st = vec2( dot(st,vec2(127.1,311.7)),
              dot(st,vec2(269.5,183.3)) );
    return -1.0 + 2.0*fract(sin(st)*43758.5453123);
}


// Gradient noise by Inigo Quilez.
float noise(in vec2 st)
{
	vec2 ip = floor(st);
	vec2 fp = fract(st);

	vec2 ci = fp*fp*(3.0 - 2.0*fp);
	return mix(mix(dot(random(ip), fp),
	               dot(random(ip + vec2(1.0, 0.0)), fp - vec2(1.0, 0.0)), ci.x),
			   mix(dot(random(ip + vec2(0.0, 1.0)), fp - vec2(0.0, 1.0)),
			       dot(random(ip + vec2(1.0, 1.0)), fp - vec2(1.0, 1.0)), ci.x),
			   ci.y);
}

float fbm(in vec2 st)
{
    float value = 0.0;
    float freq = 1.0;
    float amp = 1.0;

    for (int i = 0; i < 8; ++i)
    {
        value += amp * noise(st*freq);
        freq *= 2.0;
        amp *= 0.5;
    }

    return value;
}
